contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 1 ether);
        bool settle0Reverted;
        try c.settle() { settle0Reverted = false; } catch { settle0Reverted = true; }
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) { lockReverted = false; } catch { lockReverted = true; }
        bool settle1Reverted;
        try c.settle() { settle1Reverted = false; } catch { settle1Reverted = true; }
        assert(settle0Reverted && !lockReverted && settle1Reverted);
    }
    receive() external payable {}
}
